mapper.select:
SELECT MAX(cc.contract_id) AS contractId, MAX(pp.PROJECT_NUMBER) AS orderNo, LISTAGG(ccc.TIMES, ',') WITHIN GROUP (ORDER BY ccc.CONTRACT_ID) AS termNos, TO_CHAR(SYSDATE,'yyyy-mm-dd') AS trialTime, (NVL(SUM(ccc.PRINCIPAL), 0)+NVL(MIN(ccc.OUTSTANDING_PRINCIPAL), 0))*100 AS principal, NVL(SUM(ccc.INTEREST), 0)*100 AS interest, 0 AS penalty, 0 AS otherFee, (NVL(SUM(ccc.DUE_AMOUNT), 0)+NVL(MIN(ccc.OUTSTANDING_PRINCIPAL), 0))*100 AS payableAmount FROM CON_CONTRACT_CASHFLOW ccc INNER JOIN CON_CONTRACT cc ON ccc.CONTRACT_ID = cc.CONTRACT_ID INNER JOIN PRJ_PROJECT pp ON cc.project_id = pp.project_id WHERE AND cc.contract_status = 'INCEPT' AND cc.data_class = 'NORMAL' ccc.write_off_flag not in ('FULL') AND ccc.cf_direction='INFLOW' AND ccc.times not in (0) AND ccc.cf_item = 1 AND ccc.due_amount-nvl(ccc.RECEIVED_AMOUNT,0)>0 AND trunc(sysdate) - 85 > trunc(ccc.DUE_DATE)
AND ccc.CONTRACT_ID = #{contractId}
GROUP BY cc.CONTRACT_ID
